// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.initialize(address(0xdead));

        // Pause the contract
        vm.prank(address(0)); // DEFAULT_ADMIN_ROLE has role 0x00
        c.pause();

        // Prepare a node delegator address (non-zero)
        address[] memory ndcs = new address[](1);
        ndcs[0] = address(0x123);

        // Try calling addNodeDelegatorContractToQueue, which should revert if paused
        bool ok;
        try c.addNodeDelegatorContractToQueue(ndcs) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract reverts when paused (ok == false)
        // The buggy contract does NOT revert (ok == true), so assertTrue(ok == false) passes on reference, fails on bug
        assertTrue(ok == false);
    }
}

