    function testRegression_property() public {
        // Deploy and initialize the contract as LRTAdmin
        address admin = address(0x1234);
        vm.prank(admin);
        c.initialize(admin);  // simplified: use admin address as lrtConfig for isolation

        // Pause the contract
        vm.prank(admin);
        c.pause();

        // Now attempt to add a node delegator contract while paused
        address[] memory ndcs = new address[](1);
        ndcs[0] = address(0x5678);

        bool success;
        try c.addNodeDelegatorContractToQueue(ndcs) {
            success = true;
        } catch {
            success = false;
        }

